window.CLINICAL_DB["first_aid"]=[{"name":"成人心肺复苏（CPR）","identify":"无反应+无呼吸或仅有叹息样呼吸（判断<10秒）","steps":["确认现场安全，轻拍重呼判断意识，观察胸廓起伏判断呼吸（<10秒）","立即呼救，指定他人拨打120并取AED；记录时间","将患者仰卧于硬质平面，暴露胸部","胸外按压：两乳头连线中点（胸骨下半部），双手掌根重叠，垂直下压5-6cm，频率100-120次/分，保证胸廓完全回弹","按压与人工呼吸比30:2；开放气道（仰头抬颏法）","AED到达后立即使用，按语音提示操作（除颤时所有人离开）","持续按压直至专业人员到达或患者恢复自主循环"],"notice":"按压中断尽量<10秒；吹气可见胸廓抬起，每次约1秒；施救者疲惫时尽量换人；记录开始时间与用药情况","py":""},{"name":"儿童心肺复苏","identify":"儿童无反应+无正常呼吸","steps":["确认安全，呼救（1名施救者先做5组CPR再呼救，多人时立即分工）","单人心肺复苏按压比通气30:2，双人15:2","按压位置：婴儿两乳头连线中点下方（双指法或双拇指环抱法），儿童胸骨下半部（单手/双手）","按压深度：婴儿约4cm（胸廓前后径1/3），儿童约5cm；频率100-120次/分","开放气道，人工呼吸（婴儿口对口鼻）","AED可用儿童电极片；无儿童电极片用成人电极片（前侧位）"],"notice":"婴儿颈部柔软，开放气道避免过度后仰；按压勿过深损伤肝脏；尽快获得专业急救","py":""},{"name":"气道异物梗阻（海姆立克）","identify":"进食或异物后突发剧烈呛咳、不能说话、面色青紫、双手抓喉（V形手）","steps":["轻症能咳：鼓励用力咳嗽，观察","完全梗阻（不能说话/呼吸/咳嗽）：立即腹部冲击法（海姆立克）","施救者站于患者背后，双手环抱其上腹部（脐上两指），一手握拳拳眼向内，快速向内向上冲击，反复至异物排出","患者意识丧失时：平卧，骑跨其髋部，同样方法行腹部冲击，并准备CPR","婴幼儿（<1岁）：背部拍击5次+胸部冲击5次交替","排出后仍有呼吸困难或呛咳不止：就医排除并发症"],"notice":"孕妇或肥胖者改行胸部冲击；腹部冲击可致内脏损伤，仅用于完全梗阻；事后应就医检查","py":""},{"name":"过敏性休克","identify":"接触过敏原后突发：皮疹瘙痒+喉头水肿/呼吸困难/血压下降/意识改变（数分钟至数小时内）","steps":["立即脱离过敏原，平卧（血压低时抬高下肢），保持呼吸道通畅","立即肌注肾上腺素（成人0.3-0.5mg，1:1000，大腿外侧），可5-15分钟重复","呼叫120，吸氧，建立静脉通路，快速补液（晶体液）","抗组胺药（苯海拉明/异丙嗪）、糖皮质激素（地塞米松/甲泼尼龙）作为二线","支气管痉挛明显者吸入β2激动剂；喉头水肿严重者准备气管插管/环甲膜穿刺","监护生命体征，观察至少4-6小时（双相反应可能）"],"notice":"肾上腺素是首选救命药物，勿因犹豫延迟；正在服用β受体阻滞剂者可能对肾上腺素反应差；停用ACEI类药物（血管性水肿高危）","py":""},{"name":"急性心肌梗死","identify":"持续胸痛>20分钟（压榨样，可向左肩臂放射）、大汗、濒死感；含服硝酸甘油不缓解","steps":["立即停止活动，半卧位休息","立即嚼服阿司匹林300mg（无禁忌时）；硝酸甘油舌下含服0.5mg（低血压/右室梗死者慎用，收缩压<90禁用）","立即拨打120，避免自行驾车","心电监护，建立静脉通路","胸痛缓解不确定时，勿反复自行用药；尽快到胸痛中心","发生心跳骤停时立即CPR并取AED"],"notice":"无禁忌者尽早（120分钟内）再灌注治疗（PCI优先）；诊断未明时勿用吗啡类；疑右室梗死慎用硝酸甘油（易低血压）","py":""},{"name":"急性脑卒中（FAST）","identify":"突发：面部不对称（F）、单侧肢体无力（A）、言语不清（S）——立即拨打120（T）","steps":["立即拨打120（时间就是大脑，记录发病时间）","让患者平卧或侧卧，头偏向一侧防误吸；解开衣领","保持呼吸道通畅；如有呕吐及时清除；勿喂水喂药","勿自行服用阿司匹林等（出血性卒中可能加重出血）","禁食水，监测血压血糖（勿盲目降压）","尽快送医（4.5小时内可静脉溶栓，桥接取栓有更长时间窗）"],"notice":"发病时间精确到分钟；搬运时头部略抬高避免剧烈晃动；低血糖也会类似卒中症状，条件允许先测血糖；勿因症状缓解而推迟就医（TIA也需评估）","py":""},{"name":"低血糖","identify":"糖尿病/禁食/剧烈活动后：心慌、手抖、出汗、饥饿、乏力；严重者神志异常、昏迷（血糖<3.9mmol/L）","steps":["意识清楚能吞咽：立即口服15-20g快速升糖食物（糖水/果汁/葡萄糖片/方糖）","15分钟后复测血糖，仍低再进食15g","意识障碍或无法吞咽：不要喂食（防误吸），立即静脉注射50%葡萄糖20-40ml或肌注胰高血糖素1mg，并呼叫急救","神志恢复后进食含淀粉食物（面包/饼干）防再次低血糖","记录低血糖发作情况，寻找诱因（药物过量/漏餐/运动）"],"notice":"昏迷者严禁喂食；纠正后仍需观察（长效降糖药低血糖可反复）；反复低血糖需调整治疗方案","py":""},{"name":"糖尿病酮症酸中毒（DKA）","identify":"糖尿病者：多饮多尿加重+恶心呕吐+呼吸深快（Kussmaul呼吸）+呼气烂苹果味+脱水、意识障碍","steps":["立即呼叫120送医（需补液+胰岛素治疗）","有条件时测血糖（通常>13.9mmol/L）、尿酮体","让患者平卧，防止误吸（呕吐时侧卧）","可少量多次饮水（意识清楚时）补充水分","勿自行加用胰岛素（需在监测血糖下规范治疗）","监测神志、呼吸、脉搏"],"notice":"DKA是急诊，禁止在家自行处理；诱因常为感染/停药/应激；老年患者症状可不典型","py":""},{"name":"癫痫持续状态","identify":"癫痫发作持续>5分钟，或反复发作间歇期意识未恢复","steps":["保护患者：移开周围危险物品，勿强行按压肢体","侧卧位，头偏向一侧，解开衣领，清除口鼻分泌物防窒息","勿向口中塞任何物品（防损伤/误吸），勿强行撬牙","记录发作起始时间","立即呼叫120（>5分钟即按持续状态处理）","遵医嘱静推地西泮/咪达唑仑（院前可由急救人员执行），后续抗癫痫药维持"],"notice":"持续状态可致脑损伤，必须尽快终止；家属勿强行约束；发作停止后仍须就医评估病因","py":""},{"name":"小儿高热惊厥","identify":"6月-5岁小儿发热时突发抽搐：意识丧失、双眼上翻、四肢强直或抽动，多<5分钟","steps":["保持冷静，将患儿侧卧或平卧头偏一侧，防止误吸","移开周围危险物品，勿强行按压肢体或掰开牙关","松开衣领，保持呼吸道通畅","记录发作时间与表现","发作>5分钟或反复发作、意识不恢复：立即120","发作停止后：物理降温（温水擦浴）、必要时退热药，就医排查惊厥原因"],"notice":"大多数热性惊厥预后良好（单纯性）；勿掐人中/针刺；勿在抽搐时喂药喂水；反复或复杂性惊厥需神经科评估","py":""},{"name":"大面积烧伤","identify":"热/电/化学致皮肤烧伤，面积大（成人>10%TBSA）、累及面部/会阴/关节、或III度烧伤","steps":["脱离热源：灭火、脱去热衣（粘连时勿撕拉）","用流动冷水持续冲洗创面15-30分钟（热力烧伤早期），化学烧伤立即大量清水冲洗","创面覆盖干净敷料/保鲜膜（勿涂牙膏酱油等）","呼叫120；面积大者平卧保暖，抬高无烧伤肢体","意识清楚可少量口服补液（含盐饮料）；勿大量白水","戒指手表等环形物尽早去除防缺血；疼痛明显可冷敷"],"notice":"III度烧伤呈焦痂无痛感；勿挑破水疱；电击伤即使体表轻也可能内脏损伤；气道烧伤（面部烧伤/声音嘶哑）需警惕呼吸道梗阻","py":""},{"name":"中暑（热射病）","identify":"高温环境：体温>40℃+中枢神经异常（谵妄、抽搐、昏迷）+皮肤干热无汗","steps":["立即将患者移至阴凉通风处，脱去外衣","立即积极降温：冷水喷洒/浸泡、冰袋敷颈部腋下腹股沟、风扇吹","体温降至38℃左右停止强降温","呼叫120（热射病死亡率高，需院内支持）","意识清楚可少量多次含盐饮料；昏迷者侧卧防误吸","监测体温、意识、呼吸脉搏"],"notice":"热射病是中暑最危重型，延误处理可致多器官衰竭；勿用酒精擦浴；老年人、慢性病、户外劳动者高危","py":""},{"name":"淹溺","identify":"溺水后：呼吸心跳停止或濒死状态、意识不清、皮肤发绀","steps":["救出水面时注意施救者自身安全（用工具施救勿盲目下水）","迅速评估意识与呼吸；无呼吸心跳：立即CPR（先给2次人工呼吸再按压）","呼叫120并取AED","不要控水（倒挂/按压腹部无效且延误CPR）","复苏成功后侧卧位（防误吸），保暖","所有溺水者（即使意识恢复）均应就医观察（继发呼吸衰竭风险）"],"notice":"淡水海水溺亡机制不同但现场处理相同（都是CPR优先）；低温溺水患者复苏时间可延长","py":""},{"name":"电击伤","identify":"接触电源/雷电后：意识丧失、呼吸心跳骤停、肌肉强直、入口出口烧伤","steps":["立即切断电源（拉闸）或用于燥木棒/绝缘物挑开电线——施救者切勿直接接触触电者","确认现场安全后评估意识呼吸","无呼吸心跳：立即CPR，呼叫120","有心跳者：平卧，监测，处理入口出口烧伤（创面小但深，勿忽视）","所有电击伤者均应就医（心律失常可在数小时内发生）","高处触电坠落者注意脊柱损伤（固定制动）"],"notice":"施救者安全第一，绝缘确认前勿触碰；雷击伤同电击伤处理；警惕延迟性心律失常","py":""},{"name":"大出血止血","identify":"动脉出血（喷射状鲜红）或大量出血、面色苍白、头晕、脉速","steps":["直接压迫：无菌敷料/干净布料用力按压出血点，持续压迫","加压包扎：敷料上绷带加压缠绕","肢体动脉大出血压迫无效时：止血带（宽5cm以上）扎于伤口近心端，记录时间，每隔1小时松1-2分钟（院前短程转运可持续）","抬高出血肢体（无骨折时）","呼叫120；防休克：平卧保暖","伤口有异物时勿拔出（固定异物周围加压）"],"notice":"止血带过窄（电线铁丝）可致组织坏死；不可长时间不松；内脏出血（腹痛/呕血/黑便）不能外压，尽快送医","py":""},{"name":"骨折固定","identify":"外伤后：局部疼痛肿胀、畸形、异常活动、骨擦音、功能障碍","steps":["评估现场安全，检查有无大出血（先止血）、意识呼吸","开放性骨折：无菌敷料覆盖伤口（突出骨端勿回纳），加压止血","夹板固定：超关节固定骨折上下两个关节；无夹板可用健肢/书本/木棍","固定前勿强行复位；观察远端血液循环（皮温、颜色、脉搏）","疑似脊柱/颈部损伤：勿搬动，头颈固定，等待专业搬运","冰敷止痛（每次15-20分钟），抬高患肢"],"notice":"疑颈椎损伤切勿随意搬动（加重脊髓损伤）；躯干骨折（骨盆/肋骨）尽快专业转运；镇痛后仍需影像学确诊","py":""},{"name":"毒蛇咬伤","identify":"被蛇咬伤：伤口两个牙痕、疼痛肿胀迅速蔓延；伴恶心呕吐、视力模糊、出血倾向（神经/血液毒）","steps":["立即远离蛇，记下蛇的特征（勿追杀）","保持冷静，患肢下垂制动（减少活动防毒扩散）","去除戒指手表等；伤口局部清水冲洗","绷带包扎：从伤口近心端向心包扎（松紧以能伸入一指为度），制动","立即送医（尽快用抗蛇毒血清）；呼叫急救","记录咬伤时间；不喝酒不奔跑"],"notice":"勿用嘴吸吮毒液、勿切开伤口、勿扎死紧止血带（可致肢体坏死）、勿冰敷；超过30分钟绷带意义减小；神经毒（银环蛇）可无痛无肿但呼吸麻痹","py":""},{"name":"急性中毒","identify":"接触/误服毒物（药物、农药、酒精、清洁剂等）后：意识改变、呕吐、腹痛、抽搐、呼吸异常","steps":["立即脱离中毒现场（气体中毒先通风转移）","意识清楚误服者：保留呕吐物/药瓶样品供鉴定","勿盲目催吐（强酸强碱、石油制品、昏迷者禁催吐）","皮肤接触：脱去污染衣物，大量清水冲洗15-20分钟；眼部溅入：清水冲洗","立即呼叫120，尽量告知毒物名称、剂量、时间","昏迷者侧卧防误吸；呼吸心跳停止立即CPR"],"notice":"农药（有机磷）中毒者衣物气味明显，施救者注意防护；强酸强碱中毒禁催吐禁洗胃（可服牛奶/蛋清）；所有中毒都需医学评估","py":""},{"name":"哮喘急性发作","identify":"哮喘患者突发：呼气性呼吸困难、喘息哮鸣、不能完整说一句、三凹征；严重者沉默胸（哮鸣音消失）","steps":["立即吸入短效β2激动剂（沙丁胺醇），可每20分钟1-2喷（前1小时可至3次）","保持坐位前倾（勿平卧），松开衣领","呼叫120（中重度发作需急诊）","吸氧（有条件时）","糖皮质激素（口服泼尼松或吸入布地奈德）","监测：沉默胸、意识改变、发绀提示危重，立即急救"],"notice":"沉默胸是危险信号（气道几乎完全阻塞）；勿用镇静剂；反复发作需规范长期控制治疗","py":""},{"name":"张力性气胸","identify":"胸外伤/气胸后：进行性呼吸困难+患侧胸廓饱满+叩诊鼓音+气管向健侧移位+皮下气肿，血压下降","steps":["高度怀疑时立即呼叫120（需紧急减压）","保持半卧位，吸氧","急诊减压：粗针头于患侧第2肋间锁骨中线穿刺排气（或按急救规范行针头减压）","减压后固定针头，覆盖单向活瓣敷料","尽快转运至有条件医院行胸腔闭式引流","监测生命体征，警惕休克"],"notice":"张力性气胸可迅速致死，减压优先于转运；勿用封闭敷料完全封堵（可加重张力）；基础肺病（COPD）患者气胸更凶险","py":""}];
