window.CLINICAL_DB["highrisk_drugs"]=[{"name":"胰岛素","risk":"低血糖（严重可致昏迷死亡）、低钾","point":"用药前后监测血糖；出现心慌出汗乏力等低血糖症状立即处理（口服糖/50%葡萄糖静推）；注射后按时进餐；剂量调整需谨慎","py":""},{"name":"肝素","risk":"出血、肝素诱导性血小板减少症(HIT)、骨质疏松（长程）","point":"监测APTT/血小板；出血征象（皮肤瘀斑、牙龈、血尿）立即报告；HIT（用药5-10天血小板骤降）警惕血栓事件","py":""},{"name":"低分子肝素","risk":"出血、HIT（较肝素低但存在）","point":"肾功能不全需调剂量；腹部皮下注射；监测出血征象与血小板","py":""},{"name":"华法林","risk":"出血（颅内/消化道）、与多种药物食物相互作用","point":"定期监测INR（目标2-3，机械瓣更高）；忌擅自加服药物；大量绿叶蔬菜/饮酒影响INR；漏服处理需医嘱","py":""},{"name":"地高辛","risk":"中毒（恶心呕吐、黄视绿视、心律失常）","point":"治疗窗窄（0.5-2.0ng/mL）；低钾低镁增加中毒风险；肾功能不全减量；监测血药浓度与电解质","py":""},{"name":"胺碘酮","risk":"肺毒性（间质性肺炎）、甲状腺功能异常、QT延长、肝损伤","point":"用药前及期间查肺功能/胸片、甲状腺功能、肝功能、心电图QT；与多种药物相互作用","py":""},{"name":"阿片类（吗啡/芬太尼等）","risk":"呼吸抑制、依赖成瘾、便秘","point":"监测呼吸频率与镇静程度；老年/肺功能不全/鼾症者慎用；备纳洛酮；防滥用","py":""},{"name":"苯二氮䓬类（地西泮/咪达唑仑等）","risk":"呼吸抑制、跌倒、依赖","point":"静注速度慢；老年患者小剂量；与酒精/阿片合用呼吸抑制叠加；防长期依赖","py":""},{"name":"氯化钾（静脉）","risk":"高钾血症（可致心脏骤停）、静脉炎","point":"严禁静脉推注！常规经稀释后缓慢滴注，浓度一般≤0.3%；监测血钾与心电图；尿少慎用","py":""},{"name":"氯化钠（高浓度）","risk":"高钠血症、容量过负荷（心衰加重）","point":"高渗盐水仅限特定指征（严重低钠）；输注中监测血钠与心肺功能；滴速严格控制","py":""},{"name":"氨茶碱","risk":"心律失常、中枢兴奋（抽搐）、中毒","point":"治疗窗窄（血药浓度10-20μg/mL）；与喹诺酮/大环内酯相互作用升高浓度；监测心电图与血药浓度","py":""},{"name":"甲氨蝶呤","risk":"骨髓抑制、肝/肾毒性、口腔溃疡、全血细胞减少","point":"常规每周1次（非每日！）；次日叶酸解救；服药错误可致致命毒性；监测血常规肝肾功能","py":""},{"name":"秋水仙碱","risk":"中毒（腹泻、骨髓抑制、多器官衰竭）","point":"治疗窗窄；肝肾功能不全/合用他汀大环内酯显著增毒；出现腹泻即停药","py":""},{"name":"万古霉素","risk":"红人综合征、肾毒性、耳毒性","point":"输注≥60min；监测谷浓度（15-20mg/L重症）；联合肾毒性药物慎用；监测肾功能","py":""},{"name":"两性霉素B","risk":"肾毒性、低钾低镁、输液反应（寒战发热）","point":"输液前预处理；充分水化；监测肾功能电解质；滴注缓慢避光","py":""},{"name":"化疗药物（环磷酰胺/顺铂等）","risk":"骨髓抑制、肝肾毒性、心脏毒性、外渗组织损伤","point":"按方案执行；监测血常规肝肾功能；外渗需专科处理；防护与配伍禁忌多","py":""},{"name":"肾上腺素","risk":"高血压危象、心动过速、心律失常、脑血管意外","point":"稀释后使用（1:1000皮下/肌注，1:10000静注）；剂量精确；监测血压心率；心梗患者慎用","py":""},{"name":"缩宫素","risk":"子宫强直收缩（胎儿窘迫/子宫破裂）、水中毒","point":"按规范稀释滴注并控制速度；监测宫缩与胎心；防止过量","py":""},{"name":"硝普钠","risk":"严重低血压、氰化物中毒（长程/大剂量）","point":"持续泵入并监测血压；避光；长程(>24h)或肾功能不全者监测氰化物/硫氰酸盐","py":""},{"name":"茶碱缓释片","risk":"同氨茶碱：心律失常、抽搐","point":"个体差异大；与西咪替丁/大环内酯/喹诺酮相互作用升高浓度；监测血药浓度","py":""},{"name":"地高辛（口服）","risk":"同地高辛：中毒","point":"见地高辛条目；老年、肾衰、低钾低镁者中毒风险高；定期监测浓度","py":""},{"name":"氯吡格雷","risk":"出血、与PPI（奥美拉唑）相互作用降低疗效","point":"与奥美拉唑/埃索美拉唑联用降低抗血小板效果，可选泮托拉唑；监测出血征象","py":""},{"name":"阿司匹林","risk":"出血（消化道/颅内）、过敏（阿司匹林哮喘）","point":"胃黏膜保护（PPI）；消化道出血史慎用；哮喘患者警惕；术前停药时机遵医嘱","py":""}];
