window.CLINICAL_DB["infusion_conflict"]=[{"comb":"头孢曲松 + 含钙溶液（葡萄糖酸钙、林格液）","reason":"可形成不溶性沉淀，新生儿可致死","handle":"禁止同瓶/同管路；两药之间需充分冲管；头孢曲松与钙剂用药间隔≥48小时（尤其新生儿）","py":"","name":"头孢曲松 + 含钙溶液（葡萄糖酸钙、林格液）"},{"comb":"青霉素类 + 氨基糖苷类（混合）","reason":"β-内酰胺环破坏氨基糖苷活性","handle":"不能同瓶混合输注，应分瓶间隔给药","py":"","name":"青霉素类 + 氨基糖苷类（混合）"},{"comb":"阿昔洛韦 + 其他药物同瓶","reason":"pH不兼容可致析出沉淀","handle":"阿昔洛韦应单独输注（1小时以上），与其他药分瓶","py":"","name":"阿昔洛韦 + 其他药物同瓶"},{"comb":"两性霉素B + 含电解质溶液","reason":"高离子强度致胶体沉淀","handle":"用5%葡萄糖稀释，避免与电解质/其他药物混合","py":"","name":"两性霉素B + 含电解质溶液"},{"comb":"碳酸氢钠 + 酸性药物（多巴胺、间羟胺、维生素C等）","reason":"酸碱中和失效","handle":"不可同瓶配伍；碳酸氢钠单独输注","py":"","name":"碳酸氢钠 + 酸性药物（多巴胺、间羟胺、维生素C等）"},{"comb":"硝普钠","reason":"遇光分解","handle":"避光输注（避光输液器/黑布包裹），现配现用","py":"","name":"硝普钠"},{"comb":"万古霉素 + 肝素/地西泮","reason":"混合易沉淀/失活","handle":"万古霉素单独输注≥60分钟，不同管路","py":"","name":"万古霉素 + 肝素/地西泮"},{"comb":"氨茶碱 + 多种药物","reason":"与葡萄糖酸钙、氢化可的松、维生素C等配伍禁忌","handle":"氨茶碱单独输注，监测浓度与心律","py":"","name":"氨茶碱 + 多种药物"},{"comb":"钙剂静注 + 地高辛","reason":"钙可增强强心苷毒性","handle":"地高辛治疗期间慎用静脉钙剂，需评估血钾与血钙","py":"","name":"钙剂静注 + 地高辛"},{"comb":"胰岛素 + 含还原性药物/部分抗生素","reason":"可能失活/吸附","handle":"胰岛素一般不与其他药物同瓶混合（专用泵注）","py":"","name":"胰岛素 + 含还原性药物/部分抗生素"}];
window.CLINICAL_DB["pharmg"]=[{"name":"CYP2D6","substrate":"约25%常用药物经其代谢（可待因、他莫昔芬、抗抑郁药、β阻滞剂、抗精神病药）","effect":"慢代谢者：前药转化减少（可待因镇痛差）、部分药物血药浓度升高；超快代谢者：前药转化增多（可待因→吗啡过量风险）","action":"基因型指导可待因/他莫昔芬/帕罗西汀等用药；慢代谢者可待因改用非CYP2D6依赖镇痛药","category":"代谢酶","py":""},{"name":"CYP2C19","substrate":"氯吡格雷（前药活化）、PPI、伏立康唑、安定、部分抗抑郁药","effect":"慢代谢者：氯吡格雷活性代谢物减少→抗血小板疗效降低；PPI代谢减慢→血药浓度升高","action":"CYP2C19慢代谢+氯吡格雷：考虑替格瑞洛/普拉格雷替代（CPIC推荐）","category":"代谢酶","py":""},{"name":"CYP3A4","substrate":"约50%药物经其代谢（他汀、钙拮抗剂、环孢素、他克莫司、地高辛部分、唑类抗真菌）","effect":"抑制剂（克拉霉素、伊曲康唑、葡萄柚汁）→药物浓度升高，毒性风险；诱导剂（利福平、卡马西平、圣约翰草）→浓度降低，疗效下降","action":"合用强抑制剂/诱导剂时需调整剂量或监测浓度；避免葡萄柚汁与敏感底物同服","category":"代谢酶","py":""},{"name":"CYP2C9","substrate":"华法林（S-异构体）、苯妥英、甲苯磺丁脲、部分NSAIDs","effect":"CYP2C9*2/*3变异者代谢减慢→华法林/苯妥英浓度升高，出血/毒性风险","action":"CYP2C9变异+华法林：需更低起始剂量、更密切监测INR；苯妥英监测浓度","category":"代谢酶","py":""},{"name":"CYP1A2","substrate":"氯氮平、茶碱、咖啡因、部分抗抑郁药","effect":"吸烟（诱导）→代谢加快，氯氮平/茶碱浓度下降；氟伏沙明（抑制）→浓度升高","action":"吸烟者氯氮平/茶碱可能需增量；与氟伏沙明合用需监测；戒烟后注意浓度升高","category":"代谢酶","py":""},{"gene":"CYP2C19","drug":"氯吡格雷","effect":"慢代谢者活性代谢物生成显著减少，血小板抑制不足","action":"慢代谢者：考虑替格瑞洛或普拉格雷；或按检测报告调整（CPIC A级证据）","category":"基因位点","name":"CYP2C19","py":""},{"gene":"CYP2D6","drug":"可待因","effect":"前药需CYP2D6活化为吗啡；慢代谢者镇痛差，超快代谢者可致吗啡过量（呼吸抑制）","action":"慢代谢/超快代谢者避免使用可待因；儿童镇痛尤其谨慎（FDA黑框警告）","category":"基因位点","name":"CYP2D6","py":""},{"gene":"CYP2D6","drug":"他莫昔芬","effect":"需CYP2D6活化为endoxifen；慢代谢者活性代谢物减少，疗效可能降低","action":"慢代谢者考虑换用芳香化酶抑制剂（绝经后）或与专科讨论","category":"基因位点","name":"CYP2D6","py":""},{"gene":"CYP2C9/VKORC1","drug":"华法林","effect":"CYP2C9变异→代谢减慢；VKORC1变异→靶点敏感；两者均致低剂量出血风险","action":"用药前基因型检测可指导初始剂量（如IWPC算法）；无论基因型均需INR监测","category":"基因位点","name":"CYP2C9/VKORC1","py":""},{"gene":"CYP3A4（抑制剂）","drug":"阿托伐他汀/辛伐他汀","effect":"克拉霉素、伊曲康唑等强抑制剂使他汀浓度大幅升高","action":"避免合用或减量；出现肌痛肌无力需查CK，警惕横纹肌溶解","category":"基因位点","name":"CYP3A4（抑制剂）","py":""},{"gene":"CYP3A4（诱导剂）","drug":"环孢素/他克莫司","effect":"利福平、卡马西平等诱导剂使免疫抑制剂浓度下降","action":"合用需大幅增量并监测血药浓度；移植患者避免合用利福平","category":"基因位点","name":"CYP3A4（诱导剂）","py":""},{"gene":"CYP1A2","drug":"氯氮平","effect":"吸烟诱导代谢，氯氮平浓度可降约50%；戒烟后浓度骤升","action":"吸烟者需较高剂量；戒烟/吸烟状态变化时监测浓度并调量；与氟伏沙明合用减量","category":"基因位点","name":"CYP1A2","py":""},{"gene":"TPMT/NUDT15","drug":"硫唑嘌呤/巯嘌呤(6-MP)","effect":"变异者硫嘌呤甲基化减少，骨髓抑制（白细胞减少）风险显著升高","action":"用药前检测TPMT/NUDT15；变异者减量50-90%（CPIC）","category":"基因位点","name":"TPMT/NUDT15","py":""},{"gene":"UGT1A1*28","drug":"伊立替康","effect":"变异者SN-38葡糖醛酸化减少，中性粒细胞减少等毒性风险升高","action":"UGT1A1*28/*28纯合子建议初始减量；监测血常规","category":"基因位点","name":"UGT1A1*28","py":""},{"gene":"HLA-B*57:01","drug":"阿巴卡韦","effect":"阳性者发生超敏反应风险极高（发热、皮疹、呼吸困难，可致死）","action":"用药前必须检测；阳性者禁用阿巴卡韦（FDA黑框警告）","category":"基因位点","name":"HLA-B*57:01","py":""},{"gene":"HLA-B*15:02","drug":"卡马西平","effect":"阳性者发生Stevens-Johnson综合征/中毒性表皮坏死松解（SJS/TEN）风险高（亚洲人群）","action":"用药前检测（尤其汉族/华南人群）；阳性者禁用","category":"基因位点","name":"HLA-B*15:02","py":""},{"gene":"HLA-B*58:01","drug":"别嘌醇","effect":"阳性者SJS/TEN风险显著升高（汉族人群携带率约6-8%）","action":"用药前检测；阳性者禁用别嘌醇，考虑非布司他（仍需评估）","category":"基因位点","name":"HLA-B*58:01","py":""},{"gene":"G6PD","drug":"伯氨喹/磺胺类/呋喃妥因/萘啶酸","effect":"G6PD缺乏者氧化应激致溶血性贫血（急性血管内溶血）","action":"用药前筛查G6PD（尤其南方人群）；缺乏者避免相关药物","category":"基因位点","name":"G6PD","py":""},{"gene":"NAT2","drug":"异烟肼","effect":"慢乙酰化者异烟肼浓度升高，肝毒性/周围神经病变风险增加","action":"慢乙酰化者注意肝功能监测，常规补充维生素B6预防周围神经病变","category":"基因位点","name":"NAT2","py":""},{"gene":"CYP2D6","drug":"氟西汀/帕罗西汀","effect":"超快代谢者血药浓度低，疗效不足；慢代谢者浓度高，不良反应风险","action":"按基因型调整起始剂量；监测疗效与不良反应","category":"基因位点","name":"CYP2D6","py":""},{"gene":"SLC6A4/5-HTTLPR","drug":"SSRI类抗抑郁药","effect":"5-HTTLPR短等位基因者SSRI疗效可能较差、不良反应较多","action":"基因型可辅助选择药物，但不能单独决定治疗方案","category":"基因位点","name":"SLC6A4/5-HTTLPR","py":""}];
